	@Override
	public ItemStack getStack() {
		if (data == null) {
			return libraryInventory.getStackInSlot(0);
		}

		LibrarySpellInfo info = data.get(slot);
		if (info == null) {
			return ItemStack.EMPTY;
		}

		return info.asStack();
	}

