import epicsquid.roots.spell.SpellBase;
import epicsquid.roots.util.types.RegistryItem;
import it.unimi.dsi.fastutil.objects.Object2DoubleOpenHashMap;
import net.minecraft.client.gui.GuiScreen;
import net.minecraft.client.resources.I18n;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.ResourceLocation;
import net.minecraft.util.text.TextFormatting;
import net.minecraftforge.common.util.INBTSerializable;
import net.minecraftforge.fml.relauncher.Side;
import net.minecraftforge.fml.relauncher.SideOnly;

import javax.annotation.Nonnull;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;

public abstract class BaseModifierInstance extends RegistryItem implements INBTSerializable<NBTTagCompound>, IModifier {
	protected Modifier modifier;
	protected boolean applied;

	protected BaseModifierInstance(Modifier modifier, boolean applied) {
		this.modifier = modifier;
		this.applied = applied;
	}

	protected BaseModifierInstance() {
		this.modifier = null;
		this.applied = false;
	}

	@Override
	public boolean isDisabled() {
		return modifier != null && modifier.isDisabled();
	}

	@Override
	public Modifier getModifier() {
		return modifier;
	}

	public boolean isApplied() {
		return applied && !isDisabled();
	}

	public void setApplied() {
		this.applied = true;
	}

	@Override
	public String getIdentifier() {
		return modifier.getIdentifier();
	}

	@Override
	public String getTranslationKey() {
		return modifier.getTranslationKey();
	}

	@Override
	public String getFormatting() {
		return modifier.getFormatting();
	}

	@SideOnly(Side.CLIENT)
	public String describe() {
		if (GuiScreen.isShiftKeyDown()) {
			return getFormatting() + I18n.format(getTranslationKey()) + TextFormatting.GRAY + ": " + I18n.format(getTranslationKey() + ".desc");
		} else {
			return getFormatting() + I18n.format(getTranslationKey()) + TextFormatting.RESET;
		}
	}

	@SideOnly(Side.CLIENT)
	public String describeName() {
		return getFormatting() + I18n.format(getTranslationKey()) + TextFormatting.GRAY + ":";
	}

	@SideOnly(Side.CLIENT)
	public String describeFunction() {
		return "- " + I18n.format(getTranslationKey() + ".desc");
	}

	@SideOnly(Side.CLIENT)
	public List<String> describeCost() {
		// TODO: Sort by type
		List<String> result = new ArrayList<>();
		for (IModifierCost cost : modifier.getCosts().values()) {
			switch (cost.getCost()) {
				case NO_COST:
					result.add(I18n.format("roots.tooltip.modifier.no_cost"));
					break;
				case ADDITIONAL_COST:
					if (cost.getHerb() == null) {
						throw new NullPointerException("Additional herb modifier cost type but no herb specified.");
					}
					result.add(I18n.format("roots.tooltip.modifier.additional_cost", I18n.format(cost.getHerb().getStack().getTranslationKey() + ".name"), String.format("%.4f", cost.getValue())));
					break;
				case ALL_COST_MULTIPLIER:
					if (cost.getValue() < 0) {
						result.add(I18n.format("roots.tooltip.modifier.decreased_cost", Math.floor(cost.getValue() * 100) + "%"));
					} else {
						result.add(I18n.format("roots.tooltip.modifier.increased_cost", Math.floor(cost.getValue() * 100) + "%"));
					}
					break;
				case SPECIFIC_COST_ADJUSTMENT:
					if (cost.getValue() < 0) {
						result.add(I18n.format("roots.tooltip.modifier.specific_decreased_cost", cost.getHerb().getName(), Math.floor(cost.getValue() * 100) + "%"));
					} else {
						result.add(I18n.format("roots.tooltip.modifier.specific_increased_cost", cost.getHerb().getName(), Math.floor(cost.getValue() * 100) + "%"));
					}
					break;
				case SPECIFIC_COST_MULTIPLIER:
					if (cost.getValue() < 0) {
						result.add(I18n.format("roots.tooltip.modifier.specific_decreased_cost", cost.getHerb().getName(), Math.floor(cost.getValue() * 100) + "%"));
					} else {
						result.add(I18n.format("roots.tooltip.modifier.specific_increased_cost", cost.getHerb().getName(), Math.floor(cost.getValue() * 100) + "%"));
					}
					break;
				default:
			}
		}
		return result;
	}

	@Override
	public IModifierCore getCore() {
		if (modifier == null) {
			return BaseModifiers.AIR;
		} else {
			return modifier.getCore();
		}
	}

	@Override
	public NBTTagCompound serializeNBT() {
		NBTTagCompound tag = new NBTTagCompound();
		try {
			tag.setString("m", modifier.getRegistryName().toString());
		} catch (NullPointerException e) {
		}
		tag.setBoolean("a", applied);
		return tag;
	}

	@Override
	public void deserializeNBT(NBTTagCompound tag) {
		this.modifier = ModifierRegistry.get(new ResourceLocation(tag.getString("m")));
		this.applied = tag.getBoolean("a");
	}

	@Override
	public abstract Object2DoubleOpenHashMap<Herb> apply(Object2DoubleOpenHashMap<Herb> costs, CostType phase);

	@Override
	public boolean equals(Object o) {
		if (this == o) return true;
		if (o == null || getClass() != o.getClass()) return false;
		BaseModifierInstance that = (BaseModifierInstance) o;
		return applied == that.applied &&
				modifier.equals(that.modifier);
	}

	@Override
	public int hashCode() {
		return Objects.hash(modifier, applied);
	}

	@Nonnull
	@Override
	public ResourceLocation getRegistryName() {
		return modifier.getRegistryName();
	}

	@Override
	public List<Property<SpellBase.ModifierCost>> asProperties() {
		return Collections.emptyList();
	}
}

package epicsquid.roots.modifiers.instance.base;

import epicsquid.roots.Roots;
import epicsquid.roots.api.Herb;
import epicsquid.roots.modifiers.*;
import epicsquid.roots.spell.SpellBase;
import epicsquid.roots.spell.info.AbstractSpellInfo;
import it.unimi.dsi.fastutil.objects.Object2DoubleOpenHashMap;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.nbt.NBTTagList;
import net.minecraftforge.common.util.Constants;

import javax.annotation.Nullable;
import java.util.*;
import java.util.function.Function;
import java.util.function.Predicate;
import java.util.stream.Stream;

public abstract class BaseModifierInstanceList<T extends BaseModifierInstance> implements IModifierList<T, NBTTagCompound> {
	protected final List<T> internal;
	protected final Map<IModifierCore, T> coreToInstance;
	protected final SpellBase spell;

	public BaseModifierInstanceList(SpellBase spell, Function<Modifier, T> empty) {
		internal = new ArrayList<>();
		coreToInstance = new HashMap<>();
		for (Modifier m : spell.getModifiers()) {
			add(empty.apply(m));
		}
		this.spell = spell;
	}

	@Override
	public void clear() {
		internal.clear();
		coreToInstance.clear();
	}

	@Override
	public int size() {
		return internal.size();
	}

	@Override
	public boolean isEmpty() {
		return internal.isEmpty();
	}

	@Override
	public Stream<T> stream() {
		return internal.stream();
	}

	@Override
	public boolean contains(Object o) {
		if (o instanceof BaseModifierInstance) {
			return internal.contains(o);
		} else if (o instanceof IModifierCore) {
			return coreToInstance.containsKey(o);
		}

		return false;
	}

	@Override
	@Nullable
	public T getByCore(IModifierCore core) {
		return coreToInstance.get(core);
	}

	@Override
	@Nullable
	public T get(IModifier modifier) {
		if (modifier == null) {
			return null;
		}
		for (T mi : internal) {
			if (mi.getModifier().equals(modifier)) {
				return mi;
			}
		}
		return null;
	}

	@Override
	public Collection<T> getModifiers() {
		return internal;
	}

	public SpellBase getSpell() {
		return spell;
	}

	@SuppressWarnings("unchecked")
	@Override
	public Iterator<T> iterator() {
		return internal.iterator();
	}

	@Override
	public boolean add(T modifierInstance) {
		IModifierCore core = modifierInstance.getCore();
		coreToInstance.put(core, modifierInstance);
		internal.removeIf(o -> o.getCore().equals(core));
		return internal.add(modifierInstance);
	}

	// TODO?
	@SuppressWarnings("unchecked")
	@Override
	public boolean remove(Object o) {
		return internal.remove(o);
	}

	@Override
	public boolean removeIf(Predicate<? super T> predicate) {
		return internal.removeIf(predicate);
	}

	public Object2DoubleOpenHashMap<Herb> apply(Object2DoubleOpenHashMap<Herb> costs) {
		for (CostType type : CostType.values()) {
			for (T m : this) {
				costs = m.apply(costs, type);
			}
		}
		return costs;
	}

	@Override
	public NBTTagCompound serializeNBT() {
		NBTTagCompound result = new NBTTagCompound();
		NBTTagList list = new NBTTagList();
		for (T m : this) {
			if (m.getModifier() != null) {
				list.appendTag(m.serializeNBT());
			}
		}
		result.setString("s", spell.getRegistryName().toString());
		result.setTag("l", list);
		return result;
	}

	public void deserializeNBT(NBTTagCompound tag, Function<NBTTagCompound, T> creator) {
		NBTTagList nbt = tag.getTagList("l", Constants.NBT.TAG_COMPOUND);

		for (int i = 0; i < nbt.tagCount(); i++) {
			NBTTagCompound thisTag = nbt.getCompoundTagAt(i);
			this.add(creator.apply(thisTag));
		}

		SpellBase other = AbstractSpellInfo.getSpellFromTag(tag);
		if (!other.getRegistryName().equals(spell.getRegistryName())) {
			Roots.logger.error("Tried to deserialize mismatched ModifierInstanceLists for spell " + spell.getRegistryName() + ", trying to load for " + other.getRegistryName());
		}
	}
}

package epicsquid.roots.modifiers.instance.library;

import epicsquid.roots.api.Herb;
import epicsquid.roots.modifiers.CostType;
import epicsquid.roots.modifiers.IModifier;
import epicsquid.roots.modifiers.IModifierCost;
import epicsquid.roots.modifiers.Modifier;
import epicsquid.roots.modifiers.instance.base.BaseModifierInstance;
import epicsquid.roots.modifiers.instance.staff.StaffModifierInstance;
import it.unimi.dsi.fastutil.objects.Object2DoubleOpenHashMap;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;

import java.util.Collections;
import java.util.Map;
import java.util.Set;

public class LibraryModifierInstance extends BaseModifierInstance {
	public LibraryModifierInstance(Modifier modifier, boolean applied) {
		super(modifier, applied);
	}

	public LibraryModifierInstance(Modifier modifier) {
		super(modifier, false);
	}

	public LibraryModifierInstance() {
	}

	public static LibraryModifierInstance fromNBT(NBTTagCompound tag) {
		LibraryModifierInstance result = new LibraryModifierInstance();
		result.deserializeNBT(tag);
		return result;
	}

	public static LibraryModifierInstance fromStaff(StaffModifierInstance instance) {
		return new LibraryModifierInstance(instance.getModifier(), instance.isApplied());
	}

	public StaffModifierInstance toStaff() {
		return new StaffModifierInstance(modifier, applied, false);
	}

	@Override
	public ItemStack getStack() {
		return getCore().getStack();
	}

	@Override
	public Map<CostType, IModifierCost> getCosts() {
		return Collections.emptyMap();
	}

	@Override
	public Set<IModifier> getConflicts() {
		return modifier.getConflicts();
	}

	@Override
	public Object2DoubleOpenHashMap<Herb> apply(Object2DoubleOpenHashMap<Herb> costs, CostType phase) {
		return costs;
	}
}

package epicsquid.roots.modifiers.instance.library;

import epicsquid.roots.modifiers.instance.base.BaseModifierInstanceList;
import epicsquid.roots.modifiers.instance.staff.StaffModifierInstance;
