	private SpellBase addCost(Herb herb, double amount) {
		if (herb == null) {
			Roots.logger.error("Spell - " + this.getClass().getName() + " - added a null herb ingredient. This is a bug.");
			return this;
		}
		costs.put(herb, amount);
		return this;
	}

