package epicsquid.roots.spell.info;

import epicsquid.mysticallib.util.ItemUtil;
import epicsquid.roots.init.ModItems;
import epicsquid.roots.modifiers.instance.library.LibraryModifierInstanceList;
import epicsquid.roots.spell.SpellBase;
import epicsquid.roots.spell.info.storage.LibrarySpellStorage;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;

import java.util.Objects;

public class LibrarySpellInfo extends AbstractSpellModifiers<LibraryModifierInstanceList> {
	public static LibrarySpellInfo EMPTY = new LibrarySpellInfo();

	private boolean obtained;

	private LibrarySpellInfo() {
	}

	public LibrarySpellInfo(SpellBase spell) {
		super(spell);
		this.modifiers = new LibraryModifierInstanceList(spell);
		this.obtained = false;
	}

	@Override
	public LibraryModifierInstanceList getModifiers() {
		return modifiers;
	}

	@Override
	public void setModifiers(LibraryModifierInstanceList libraryModifierInstances) {
		this.modifiers = libraryModifierInstances;
	}

	public boolean isObtained() {
		return obtained;
	}

	public void setObtained() {
		setObtained(true);
	}

	public void setObtained(boolean value) {
		this.obtained = value;
	}

	@Override
	public NBTTagCompound serializeNBT() {
		NBTTagCompound result = super.serializeNBT();
		result.setTag("m", modifiers.serializeNBT());
		result.setBoolean("o", obtained);
		return result;
	}

	@Override
	public void deserializeNBT(NBTTagCompound nbt) {
		super.deserializeNBT(nbt);
		SpellBase spell = getSpell();
		if (spell != null) {
			this.modifiers = new LibraryModifierInstanceList(spell);
			this.modifiers.deserializeNBT(nbt.getCompoundTag("m"));
			this.obtained = nbt.getBoolean("o");
		}
	}

	@Override
	public boolean isEmpty() {
		return this == EMPTY;
	}

	@Override
	public ItemStack asStack() {
		ItemStack stack = new ItemStack(ModItems.spell_icon);
		NBTTagCompound comp = ItemUtil.getOrCreateTag(stack);
		comp.setBoolean("library", true);
		LibrarySpellStorage storage = LibrarySpellStorage.fromStack(stack);
		Objects.requireNonNull(storage).addSpell(this);
		return stack;
	}

	public StaffSpellInfo toStaff() {
		SpellBase spell = getSpell();
		if (spell != null) {
			StaffSpellInfo info = new StaffSpellInfo(spell);
			info.setModifiers(modifiers.toStaff());
			return info;
		} else {
			return StaffSpellInfo.EMPTY;
		}
	}

	public static LibrarySpellInfo fromNBT(NBTTagCompound tag) {
		LibrarySpellInfo instance = new LibrarySpellInfo();
		instance.deserializeNBT(tag);
		return instance;
	}

	public static LibrarySpellInfo fromStaff(StaffSpellInfo incoming) {
		SpellBase spell = incoming.getSpell();
		if (spell != null) {
			LibrarySpellInfo instance = new LibrarySpellInfo(spell);
			instance.setObtained(true);
			instance.setModifiers(incoming.getModifiers().toLibrary());
			return instance;
		} else {
			return LibrarySpellInfo.EMPTY;
		}
	}
}

package epicsquid.roots.spell.info;

import epicsquid.mysticallib.util.ItemUtil;
import epicsquid.roots.Roots;
import epicsquid.roots.init.ModItems;
import epicsquid.roots.modifiers.instance.staff.StaffModifierInstance;
import epicsquid.roots.modifiers.instance.staff.StaffModifierInstanceList;
import epicsquid.roots.spell.FakeSpell;
import epicsquid.roots.spell.SpellBase;
import epicsquid.roots.spell.SpellRegistry;
import epicsquid.roots.spell.info.storage.StaffSpellStorage;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.ResourceLocation;

import javax.annotation.Nullable;
import java.util.Objects;

public class StaffSpellInfo extends AbstractSpellModifiers<StaffModifierInstanceList> {
	public static StaffSpellInfo EMPTY = new StaffSpellInfo(FakeSpell.INSTANCE);
	private int cooldown = -1;
	private long cooldownStop = -1;

	public StaffSpellInfo(SpellBase spell) {
		super(spell);
		modifiers = new StaffModifierInstanceList(spell);
	}

	@Override
	public StaffModifierInstanceList getModifiers() {
		return modifiers;
	}

	@Override
	public void setModifiers(StaffModifierInstanceList modifiers) {
		this.modifiers = modifiers;
	}

	public boolean tick() {
		if (this.cooldown == -1) {
			return false;
		}
		this.cooldown--;
		if (this.cooldown <= 0) {
			this.cooldown = -1;
		}
		return true;
	}

	public boolean onCooldown() {
		return this.cooldown != -1;
	}

	public int cooldownLeft() {
		return cooldown;
	}

	public int cooldownTotal() {
		SpellBase spell = getSpell();
		if (spell != null) {
			return spell.getCooldown();
		} else {
			return 0;
		}
	}

	public void use(long cd) {
		this.cooldown = cooldownTotal();
		this.cooldownStop = cd + cooldown;
	}

	public boolean validate(long cd) {
		if (this.cooldown != -1 && cd > this.cooldownStop) {
			this.cooldown = -1;
			return true;
		}
		return false;
	}

	@Override
	public NBTTagCompound serializeNBT() {
		NBTTagCompound result = super.serializeNBT();
		result.setTag("m", modifiers.serializeNBT());
		result.setInteger("c", cooldown);
		result.setLong("l", cooldownStop);
		return result;
	}

	@Override
	public void deserializeNBT(NBTTagCompound nbt) {
		super.deserializeNBT(nbt);
		this.modifiers = StaffModifierInstanceList.fromNBT(nbt.getCompoundTag("m"));
		this.cooldown = nbt.getInteger("c");
		this.cooldownStop = nbt.getLong("l");
	}

	@Override
	public boolean isEmpty() {
		return this == EMPTY;
	}

	@Nullable
	public static StaffSpellInfo fromNBT(NBTTagCompound tag) {
		SpellBase spell = getSpellFromTag(tag);
		if (spell == null) {
			return null;
		}
		StaffSpellInfo instance = new StaffSpellInfo(spell);
		instance.deserializeNBT(tag);
		return instance;
	}

	@Nullable
	public static StaffSpellInfo fromRegistry(String name) {
		ResourceLocation rl = new ResourceLocation(Roots.MODID, name);
		SpellBase spell = SpellRegistry.getSpell(rl);
		if (spell == null) {
			return null;
		}
		return new StaffSpellInfo(spell);
	}

	public static StaffSpellInfo fromLibrary(LibrarySpellInfo incoming) {
		SpellBase spell = incoming.getSpell();
		if (spell != null) {
			StaffSpellInfo info = new StaffSpellInfo(spell);
			info.setModifiers(incoming.getModifiers().toStaff());
			return info;
		} else {
			return StaffSpellInfo.EMPTY;
		}
	}

	public static StaffSpellInfo fromSpell(SpellBase spell, boolean modifiers) {
		StaffSpellInfo info = new StaffSpellInfo(spell);
		if (modifiers) {
			for (StaffModifierInstance modifier : info.getModifiers()) {
				modifier.setApplied();
			}
		}
		return info;
	}

	public LibrarySpellInfo toLibrary() {
		SpellBase spell = getSpell();
		if (spell != null) {
			LibrarySpellInfo info = new LibrarySpellInfo(spell);
			info.setObtained();
			info.setModifiers(getModifiers().toLibrary());
			return info;
		} else {
			return LibrarySpellInfo.EMPTY;
		}
	}

	@Override
	public ItemStack asStack() {
		ItemStack stack = new ItemStack(ModItems.spell_icon);
		NBTTagCompound comp = ItemUtil.getOrCreateTag(stack);
		comp.setBoolean("staff", true);
		StaffSpellStorage storage = StaffSpellStorage.fromStack(stack);
		storage.addSpell(this);
		storage.setSelectedSlot(1);
		storage.saveToStack();
		return stack;
	}

	@Override
	public boolean equals(Object o) {
		if (this == o) return true;
		if (o == null || getClass() != o.getClass()) return false;
		StaffSpellInfo that = (StaffSpellInfo) o;
		return cooldown == that.cooldown;
	}

	@Override
	public int hashCode() {
		return Objects.hash(cooldown);
	}
}

package epicsquid.roots.spell.info.storage;

import epicsquid.mysticallib.util.ItemUtil;
import epicsquid.roots.spell.SpellBase;
import epicsquid.roots.spell.info.AbstractSpellInfo;
import net.minecraft.client.resources.I18n;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.text.TextFormatting;
import net.minecraftforge.common.util.INBTSerializable;
import net.minecraftforge.fml.relauncher.Side;
import net.minecraftforge.fml.relauncher.SideOnly;

import javax.annotation.Nullable;
import java.util.function.Function;

public abstract class AbstractSpellStorage<V extends AbstractSpellInfo> implements INBTSerializable<NBTTagCompound> {
	protected ItemStack stack;
	protected int selectedSlot = 1;

	public AbstractSpellStorage() {
	}

	protected AbstractSpellStorage(ItemStack stack) {
		this.stack = stack;
	}

	public abstract boolean hasSpellInSlot();

	public abstract boolean isEmpty();

	public abstract boolean isValid();

	@Nullable
	public abstract V getSpellInSlot(int slot);

	public int getCooldownLeft() {
		return -1;
	}

	public int getCooldown() {
		return -1;
	}

	@Nullable
	public V getSelectedInfo() {
		return getSpellInSlot(selectedSlot);
	}

	@SideOnly(Side.CLIENT)
	public String formatSelectedSpell() {
		V info = getSelectedInfo();
		if (info == null) {
			return "";
		}

		SpellBase spell = info.getSpell();
		if (spell == null) {
			return "";
		}
		return "(" + spell.getTextColor() + TextFormatting.BOLD + I18n.format("roots.spell." + spell.getName() + ".name") + TextFormatting.RESET + ")";
	}

	public abstract void clearSelectedSlot();

	public abstract void clearSlot(int slot);

	public int getSelectedSlot() {
		return this.selectedSlot;
	}

	public void setSelectedSlot(int slot) {
		this.selectedSlot = slot;
	}

	public abstract void previousSlot();

	public abstract void nextSlot();

	public abstract void addSpell(V spell);

	public abstract void setSpellToSlot(int slot, V spell);

	public int getNextFreeSlot() {
		return -1;
	}

	public boolean hasFreeSlot() {
		return getNextFreeSlot() != -1;
	}

	@Override
	public abstract NBTTagCompound serializeNBT();

	@Override
	public abstract void deserializeNBT(NBTTagCompound tag);

	@Nullable
	protected static <V extends AbstractSpellInfo, T extends AbstractSpellStorage<V>> T fromStack(ItemStack stack, Function<ItemStack, T> factory) {
		T result = factory.apply(stack);
		if (!result.isValid()) {
			return null;
		}
		NBTTagCompound tag = ItemUtil.getOrCreateTag(stack);
		if (tag.hasKey("spell_storage")) {
			result.deserializeNBT(tag.getCompoundTag("spell_storage"));
		} else if (tag.hasKey("spell_holder")) {
			result.deserializeNBT(tag.getCompoundTag("spell_holder"));
			tag.removeTag("spell_holder");
			result.saveToStack();
		}
		return result;
	}

	public void saveToStack() {
		NBTTagCompound tag = ItemUtil.getOrCreateTag(stack);
		tag.setTag("spell_storage", this.serializeNBT());
	}
}

package epicsquid.roots.spell.info.storage;

import com.google.common.collect.Sets;
import epicsquid.roots.Roots;
import epicsquid.roots.modifiers.Modifier;
import epicsquid.roots.modifiers.instance.staff.StaffModifierInstance;
import epicsquid.roots.spell.SpellAugment;
import epicsquid.roots.spell.SpellExtension;
import epicsquid.roots.spell.SpellGrowthInfusion;
import epicsquid.roots.spell.SpellStormCloud;
import epicsquid.roots.spell.info.StaffSpellInfo;
import epicsquid.roots.util.SpellUtil;
import it.unimi.dsi.fastutil.ints.Int2ObjectMap;
import it.unimi.dsi.fastutil.ints.Int2ObjectOpenHashMap;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraftforge.common.util.Constants;

import javax.annotation.Nullable;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.Set;

// TODO:
public class StaffSpellStorage extends AbstractSpellStorage<StaffSpellInfo> {
	public static int MAX_SPELL_SLOT = 5;
	public static int MIN_SPELL_SLOT = 1;

	private Int2ObjectOpenHashMap<StaffSpellInfo> spells = new Int2ObjectOpenHashMap<>();

	public StaffSpellStorage(ItemStack stack) {
		this.stack = stack;
	}

	@Override
	public boolean hasSpellInSlot() {
		return spells.get(this.selectedSlot) != null;
	}

	@Override
	public boolean isEmpty() {
		for (StaffSpellInfo v : this.spells.values()) {
			if (v != null) {
				return false;
			}
		}
		return true;
	}

	@Override
	public boolean isValid() {
		return SpellUtil.isValidStaff(stack);
	}

	@Override
	@Nullable
	public StaffSpellInfo getSpellInSlot(int slot) {
		if (slot < MIN_SPELL_SLOT || slot > MAX_SPELL_SLOT) {
			throw new IllegalStateException("Tried to get spell for invalid slot " + slot);
		}
		return spells.get(slot);
	}

	public Collection<StaffSpellInfo> getSpells() {
		List<StaffSpellInfo> result = new ArrayList<>();
		for (int i = MIN_SPELL_SLOT; i <= MAX_SPELL_SLOT; i++) {
			StaffSpellInfo info = spells.get(i);
			if (info != null) {
				result.add(info);
			}
		}
		return result;
	}

	public void tick(long cd) {
		boolean ticked = false;
		for (StaffSpellInfo spell : getSpells()) {
			if (spell.tick()) {
				ticked = true;
			}
			if (spell.validate(cd)) {
				ticked = true;
			}
		}
		if (ticked) {
			saveToStack();
		}
	}

	@Override
	public int getCooldownLeft() {
		StaffSpellInfo info = getSelectedInfo();
		if (info == null) {
			return -1;
		}
		return info.cooldownLeft();
	}

	public boolean onCooldown() {
		StaffSpellInfo info = getSelectedInfo();
		if (info == null) {
			return false;
		}
		return info.onCooldown();
	}

	@Override
	public int getCooldown() {
		StaffSpellInfo info = getSelectedInfo();
		if (info == null) {
			return -1;
		}
		return info.cooldownTotal();
	}

	public void setCooldown(long cd) {
		StaffSpellInfo info = getSelectedInfo();
		if (info != null) {
			info.use(cd);
		}
		saveToStack();
	}

	@Override
	@Nullable
	public StaffSpellInfo getSelectedInfo() {
		return spells.get(this.selectedSlot);
	}

	@Override
	public void clearSelectedSlot() {
		spells.put(this.selectedSlot, null);
		saveToStack();
	}

	@Override
	public void clearSlot(int slot) {
		if (slot <= MAX_SPELL_SLOT && slot >= MIN_SPELL_SLOT) {
			spells.put(slot, null);
			saveToStack();
		} else {
			throw new IllegalArgumentException("Invalid argument for StaffSpellStorage::clearSlot, `slot`: " + slot + " cannot be contained within the constraints of " + MIN_SPELL_SLOT + "-" + MAX_SPELL_SLOT);
		}
	}

	@Override
	public void previousSlot() {
		if (this.isEmpty()) {
			// Problematic TODO
			setSelectedSlot(1);
			saveToStack();
			return;
		}

		int originalSlot = selectedSlot;

		for (int i = selectedSlot - 1; i >= MIN_SPELL_SLOT; i--) {
			if (spells.get(i) != null) {
				setSelectedSlot(i);
				saveToStack();
				return;
			}
		}
		for (int i = MAX_SPELL_SLOT; i >= originalSlot; i--) {
			if (spells.get(i) != null) {
				setSelectedSlot(i);
				saveToStack();
				return;
			}
		}

		setSelectedSlot(originalSlot);
		saveToStack();
	}

	@Override
	public void nextSlot() {
		if (this.isEmpty()) {
			// Problematic TODO
			setSelectedSlot(1);
			saveToStack();
			return;
		}

		int originalSlot = selectedSlot;

		if (selectedSlot + 1 <= MAX_SPELL_SLOT) {
			for (int i = selectedSlot + 1; i <= MAX_SPELL_SLOT; i++) {
				if (spells.get(i) != null) {
					setSelectedSlot(i);
					saveToStack();
					return;
				}
			}
		}

		for (int i = MIN_SPELL_SLOT; i < originalSlot; i++) {
			if (spells.get(i) != null) {
				setSelectedSlot(i);
				saveToStack();
				return;
			}
		}

		setSelectedSlot(originalSlot);
		saveToStack();
	}

	@Override
	public void addSpell(StaffSpellInfo spell) {
		if (hasFreeSlot()) {
			setSpellToSlot(getNextFreeSlot(), spell);
			saveToStack();
		}
	}

	@Override
	public void setSpellToSlot(int slot, StaffSpellInfo spell) {
		if (slot <= MAX_SPELL_SLOT && slot >= MIN_SPELL_SLOT) {
			this.spells.put(slot, spell);
			saveToStack();
		} else {
			throw new IllegalArgumentException("Invalid argument for StaffSpellStorage::setSpellToSlot, `slot`: " + slot + " cannot be contained within the constraints of " + MIN_SPELL_SLOT + "-" + MAX_SPELL_SLOT);
		}
	}

	@Override
	public int getNextFreeSlot() {
		for (int i = MIN_SPELL_SLOT; i <= MAX_SPELL_SLOT; i++) {
			if (spells.getOrDefault(i, null) == null) {
				return i;
			}
		}
		return -1;
	}

	@Override
	public boolean hasFreeSlot() {
		return getNextFreeSlot() != -1;
	}

	@Override
	public NBTTagCompound serializeNBT() {
		if (getSelectedInfo() == null) {
			for (int i = MIN_SPELL_SLOT; i <= MAX_SPELL_SLOT; i++) {
				if (spells.get(i) != null) {
					setSelectedSlot(i);
					break;
				}
			}
		}
		NBTTagCompound compound = new NBTTagCompound();
		NBTTagCompound spells = new NBTTagCompound();
		for (Int2ObjectMap.Entry<StaffSpellInfo> entry : this.spells.int2ObjectEntrySet()) {
			spells.setTag(String.valueOf(entry.getIntKey()), entry.getValue() == null ? new NBTTagCompound() : entry.getValue().serializeNBT());
		}
		compound.setTag("spells", spells);
		compound.setInteger("selectedSlot", this.selectedSlot);
		return compound;
	}

	@Override
	public void deserializeNBT(NBTTagCompound tag) {
		if (tag.hasKey("spells", Constants.NBT.TAG_COMPOUND)) {
			NBTTagCompound spells = tag.getCompoundTag("spells");
			Set<String> keys = spells.getKeySet();
			if (keys.size() > MAX_SPELL_SLOT) {
				Roots.logger.error("Invalid spell when deserializing storage: spells list is " + keys.size() + " which is greater than MAX_SPELL_SLOT " + MAX_SPELL_SLOT + ": " + tag.toString());
			}
			for (String key : keys) {
				int value = Integer.parseInt(key);
				StaffSpellInfo info = StaffSpellInfo.fromNBT(spells.getCompoundTag(key));
				//Probably just spell swapping
				//Roots.logger.error("Tried to deserialize spell " + spells.getCompoundTag(key) + " but got null!");
				this.spells.put(value, info);
			}
			this.selectedSlot = tag.getInteger("selectedSlot");
		} else if (tag.hasKey("spell_0")) {
			for (int i = 0; i < 5; i++) {
				if (tag.hasKey("spell_" + i)) {
					StaffSpellInfo info = resolveSpell(tag.getString("spell_" + i));
					spells.put(i + 1, info);
				}
			}
			this.selectedSlot = tag.getInteger("selectedSlot");
			this.saveToStack();
		}
	}

	private static Set<String> REMOVED_SPELLS = Sets.newHashSet("spell_iced_touch", "spell_light_drifter", "spell_magnetism", "spell_rampant_growth", "spell_second_wind", "spell_sense_animals", "spell_sense_danger");

	@Nullable
	private static StaffSpellInfo resolveSpell(String spell_name) {
		if (!REMOVED_SPELLS.contains(spell_name)) {
			return StaffSpellInfo.fromRegistry(spell_name);
		} else {
			StaffSpellInfo info = null;
			switch (spell_name) {
				case "spell_iced_touch":
					info = StaffSpellInfo.fromSpell(SpellStormCloud.instance, false);
					break;
				case "spell_light_drifter":
					info = StaffSpellInfo.fromSpell(SpellAugment.instance, false);
					for (StaffModifierInstance mod : info.getModifiers()) {
						if (mod.getModifier() == SpellAugment.LIGHT_DRIFTER) {
							mod.setApplied();
							mod.setEnabled(true);
						}
					}
					break;
				case "spell_magnetism":
					info = StaffSpellInfo.fromSpell(SpellAugment.instance, false);
					for (StaffModifierInstance mod : info.getModifiers()) {
						if (mod.getModifier() == SpellAugment.MAGNETISM) {
							mod.setApplied();
							mod.setEnabled(true);
						}
					}
					break;
				case "spell_rampant_growth":
					info = StaffSpellInfo.fromSpell(SpellGrowthInfusion.instance, false);
					for (StaffModifierInstance mod : info.getModifiers()) {
						Modifier m = mod.getModifier();
						if (m == SpellGrowthInfusion.RADIUS1) {
							mod.setApplied();
							mod.setEnabled(true);
						}
						if (m == SpellGrowthInfusion.RADIUS2 || m == SpellGrowthInfusion.RADIUS3) {
							mod.setApplied();
						}
					}
					break;
				case "spell_second_wind":
					info = StaffSpellInfo.fromSpell(SpellAugment.instance, false);
					for (StaffModifierInstance mod : info.getModifiers()) {
						if (mod.getModifier() == SpellAugment.SECOND_WIND) {
							mod.setApplied();
							mod.setEnabled(true);
						}
					}
					break;
				case "spell_sense_animals":
					info = StaffSpellInfo.fromSpell(SpellExtension.instance, false);
					for (StaffModifierInstance mod : info.getModifiers()) {
						if (mod.getModifier() == SpellExtension.SENSE_ANIMALS) {
							mod.setApplied();
							mod.setEnabled(true);
						}
					}
					break;
				case "spell_sense_danger":
					info = StaffSpellInfo.fromSpell(SpellExtension.instance, false);
					for (StaffModifierInstance mod : info.getModifiers()) {
						if (mod.getModifier() == SpellExtension.SENSE_DANGER) {
							mod.setApplied();
							mod.setEnabled(true);
						}
					}
					break;
			}

			return info;
		}
	}

	@Nullable
	public static StaffSpellStorage fromStack(ItemStack stack) {
		return fromStack(stack, StaffSpellStorage::new);
	}
}

package epicsquid.roots.tileentity;

import epicsquid.mysticallib.network.PacketHandler;
import epicsquid.mysticallib.tile.TileBase;
import epicsquid.mysticallib.util.ItemUtil;
