package epicsquid.roots.util;

import epicsquid.roots.init.ModItems;
import epicsquid.roots.modifiers.ModifierRegistry;
import epicsquid.roots.modifiers.instance.library.LibraryModifierInstance;
import epicsquid.roots.modifiers.instance.library.LibraryModifierInstanceList;
import epicsquid.roots.modifiers.instance.staff.StaffModifierInstance;
import epicsquid.roots.modifiers.instance.staff.StaffModifierInstanceList;
import epicsquid.roots.spell.SpellBase;
import epicsquid.roots.spell.info.LibrarySpellInfo;
import epicsquid.roots.spell.info.StaffSpellInfo;
import epicsquid.roots.spell.info.storage.StaffSpellStorage;
import epicsquid.roots.world.data.SpellLibraryData;
import epicsquid.roots.world.data.SpellLibraryRegistry;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.item.ItemStack;
import net.minecraft.util.EnumFacing;
import net.minecraftforge.items.CapabilityItemHandler;
import net.minecraftforge.items.IItemHandler;

public class SpellUtil {
	public static boolean isValidStaff(ItemStack stack) {
		return stack.getItem() == ModItems.staff || stack.getItem() == ModItems.spell_dust || stack.getItem() == ModItems.spell_icon;
	}

	public static boolean isStaff(ItemStack stack) {
		return stack.getItem() == ModItems.staff;
	}

	public static boolean isValidDust(ItemStack stack) {
		return stack.getItem() == ModItems.spell_dust || stack.getItem() == ModItems.spell_icon;
	}

	public static void updateModifiers(EntityPlayer player) {
		if (player.world.isRemote) {
			return;
		}

		IItemHandler handler = player.getCapability(CapabilityItemHandler.ITEM_HANDLER_CAPABILITY, EnumFacing.UP);
		if (handler == null) {
			return;
		}

		for (int i = 0; i < handler.getSlots(); i++) {
			ItemStack stack = handler.getStackInSlot(i);
			if (isStaff(stack)) {
				updateModifiers(stack, player);
			}
		}
	}

	public static boolean updateModifiers(ItemStack stack, EntityPlayer player) {
		if (player.world.isRemote) {
			return false;
		}

		if (!isStaff(stack)) {
			return false;
		}

		StaffSpellStorage storage = StaffSpellStorage.fromStack(stack);
		if (storage == null) {
			return false;
		}

		SpellLibraryData data = SpellLibraryRegistry.getData(player);

		for (StaffSpellInfo info : storage.getSpells()) {
			LibraryModifierInstanceList libraryModifiers = data.getModifiers(info.toLibrary());
			if (libraryModifiers != null) {
				info.getModifiers().removeIf(o -> libraryModifiers.get(o.getModifier()) == null || ModifierRegistry.get(o.getModifier()) == null);

				data.updateSpell(info.toLibrary());
			}
		}

		for (StaffSpellInfo info : storage.getSpells()) {
			SpellBase spell = info.getSpell();
			if (spell == null) {
				continue;
			}
			LibrarySpellInfo current = data.getData(spell);
			StaffModifierInstanceList modifiers = info.getModifiers();
			for (LibraryModifierInstance instance : current.getModifiers()) {
				if (instance.isApplied()) {
					StaffModifierInstance currentInstance = modifiers.get(instance.getModifier());
					if (currentInstance == null) {
						throw new NullPointerException("Trying to update " + spell.getRegistryName() + " item for player " + player + " but incoming modifier list contained " + instance.getModifier().getRegistryName() + " but our copy does not!");
					}
					currentInstance.setApplied();
				}
			}
		}

		storage.saveToStack();
		return true;
	}
}

package epicsquid.roots.world.data;

import epicsquid.roots.modifiers.instance.library.LibraryModifierInstance;
import epicsquid.roots.modifiers.instance.library.LibraryModifierInstanceList;
import epicsquid.roots.spell.SpellBase;
import epicsquid.roots.spell.SpellRegistry;
import epicsquid.roots.spell.info.LibrarySpellInfo;
import epicsquid.roots.spell.info.SpellDustInfo;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.nbt.NBTTagList;
import net.minecraft.world.storage.WorldSavedData;
import net.minecraftforge.common.util.Constants;

import javax.annotation.Nullable;
import java.util.*;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.stream.Collectors;

@SuppressWarnings("NullableProblems")
public class SpellLibraryData extends WorldSavedData implements Iterable<LibrarySpellInfo> {
	private static final String identifier = "SpellData-";
	private Map<SpellBase, LibrarySpellInfo> spells = new HashMap<>();
	private List<LibrarySpellInfo> list = null;

	private UUID uuid;

	public static String name(UUID uuid) {
		return identifier + uuid.toString();
	}

	public SpellLibraryData(String name) {
		super(name);
		this.uuid = UUID.fromString(name.replace(identifier, ""));
		generateMap();
	}

	public SpellLibraryData(UUID uuid) {
		super(name(uuid));
		this.uuid = uuid;
		generateMap();
	}

	public SpellLibraryData(EntityPlayer player) {
		super(identifier + player.getCachedUniqueIdString());
		this.uuid = player.getUniqueID();
		generateMap();
	}

	private void generateMap() {
		spells.clear();
		for (SpellBase spell : SpellRegistry.spellRegistry.values()) {
			spells.put(spell, new LibrarySpellInfo(spell));
		}
	}

	public void addSpell(SpellDustInfo info) {
		SpellBase spell = info.getSpell();
		if (spell != null) {
			LibrarySpellInfo libinfo = spells.get(spell);
			libinfo.setObtained();
			list = null;
			markDirty();
		}
	}

	public void addSpell(SpellBase spell) {
		LibrarySpellInfo info = spells.get(spell);
		info.setObtained();
		list = null;
		markDirty();
	}

	public LibrarySpellInfo getData(SpellBase spell) {
		return spells.get(spell);
	}

	@Nullable
	public LibraryModifierInstanceList getModifiers(LibrarySpellInfo incoming) {
		SpellBase spell = incoming.getSpell();
		if (spell != null) {
			LibrarySpellInfo current = getData(spell);
			return current.getModifiers();
		} else {
			return null;
		}
	}

	public void updateSpell(LibrarySpellInfo incoming) {
		SpellBase spell = incoming.getSpell();
		if (spell == null) {
			return;
		}
		LibrarySpellInfo current = getData(spell);
		if (!current.isObtained() && incoming.isObtained()) {
			current.setObtained();
		}
		for (LibraryModifierInstance instance : incoming.getModifiers()) {
			if (instance.isApplied()) {
				LibraryModifierInstance currentInstance = current.getModifiers().get(instance.getModifier());
				if (currentInstance == null) {
					throw new NullPointerException("Trying to update " + spell.getRegistryName() + " for player " + uuid + " but incoming modifier list contained " + instance.getModifier().getRegistryName() + " but our copy does not!");
				}
				if (!currentInstance.isApplied()) {
					currentInstance.setApplied();
				}
			}
		}
		list = null;
		markDirty();
	}

	@Override
	public void readFromNBT(NBTTagCompound nbt) {
		NBTTagList list = nbt.getTagList("spells", Constants.NBT.TAG_COMPOUND);
		generateMap();
		for (int i = 0; i < list.tagCount(); i++) {
			LibrarySpellInfo instance = LibrarySpellInfo.fromNBT(list.getCompoundTagAt(i));
			SpellBase spell = instance.getSpell();
			if (spell != null) {
				spells.put(spell, instance);
			}
		}
		uuid = nbt.getUniqueId("uuid");
		this.list = null;
	}

	@Override
	public NBTTagCompound writeToNBT(NBTTagCompound compound) {
		NBTTagList list = new NBTTagList();
		for (LibrarySpellInfo instance : spells.values()) {
			if (instance == null) {
				continue;
			}
			list.appendTag(instance.serializeNBT());
		}
		compound.setTag("spells", list);
		compound.setUniqueId("uuid", uuid);
		return compound;
	}

	public List<LibrarySpellInfo> asList() {
		if (list == null) {
			list = spells.values()
			             .stream()
			             .filter(o -> o.getSpell() != null)
			             .filter(LibrarySpellInfo::isObtained)
			             .sorted(Comparator.comparing(a -> a.getSpell() == null ? "" : a.getSpell().getRegistryName().getPath()))
			             .collect(Collectors.toList());
		}
		return list;
	}

	@Override
	public Iterator<LibrarySpellInfo> iterator() {
		return asList().iterator();
	}

	@Nullable
	public LibrarySpellInfo get(int slot) {
		List<LibrarySpellInfo> info = asList();
		if (slot < info.size()) {
			return info.get(slot);
		}
		return null;
	}

	public int size() {
		return asList().size();
	}
}

package epicsquid.roots.world.data;

import net.minecraft.entity.player.EntityPlayer;

import java.util.UUID;

public class SpellLibraryRegistry extends UUIDRegistry<SpellLibraryData> {
	public static SpellLibraryRegistry INSTANCE = new SpellLibraryRegistry();

	private SpellLibraryRegistry() {
		super(SpellLibraryData.class, SpellLibraryData::name, SpellLibraryData::new);
	}

	public static SpellLibraryData getData(UUID id) {
		return INSTANCE.getDataInternal(id);
	}

	public static SpellLibraryData getData(EntityPlayer player) {
		return getData(player.getUniqueID());
	}

	public static SpellLibraryData clearData(UUID id) {
		return INSTANCE.clearDataInternal(id);
	}

	public static SpellLibraryData clearData(EntityPlayer player) {
		return clearData(player.getUniqueID());
	}
}

package epicsquid.roots.world.data;

import net.minecraft.world.WorldServer;
import net.minecraft.world.storage.MapStorage;
import net.minecraft.world.storage.WorldSavedData;
import net.minecraftforge.fml.common.FMLCommonHandler;

import java.util.UUID;
import java.util.function.Function;

@SuppressWarnings("WeakerAccess")
public abstract class UUIDRegistry<T extends WorldSavedData> {
	private Class<? extends T> clazz;
	private Function<UUID, String> nameConverter;
	private Function<UUID, T> builder;

	public UUIDRegistry(Class<? extends T> clazz, Function<UUID, String> nameConverter, Function<UUID, T> builder) {
		this.clazz = clazz;
		this.nameConverter = nameConverter;
		this.builder = builder;
	}

	@SuppressWarnings("unchecked")
	public T getDataInternal(UUID id) {
		WorldServer server = FMLCommonHandler.instance().getMinecraftServerInstance().getWorld(0);
		MapStorage storage = server.getMapStorage();
		if (storage == null) {
			throw new NullPointerException("Map storage is null");
		}
		T data = (T) storage.getOrLoadData(clazz, nameConverter.apply(id));

		if (data == null) {
			data = builder.apply(id);
			server.getMapStorage().setData(nameConverter.apply(id), data);
		}

		return data;
	}

	public T clearDataInternal(UUID id) {
		WorldServer server = FMLCommonHandler.instance().getMinecraftServerInstance().getWorld(0);
		MapStorage storage = server.getMapStorage();
		if (storage == null) {
			throw new NullPointerException("Map storage is null");
		}

		T data = builder.apply(id);
		server.getMapStorage().setData(nameConverter.apply(id), data);
		data.markDirty();
		server.getMapStorage().saveAllData();

		return data;
	}
}
